insert into app.item_group(code,name,owner_dept,source,is_dummy) values ('CARD_READER','카드리더기','marketing','seed',true),('PAPER','용지','marketing','seed',true),('TONER','토너','service','seed',true) on conflict (code) do nothing;
insert into app.item_group_item(item_code, group_code) select item_code, 'CARD_READER' from (select i.item_code from core.v_item i where description ilike '%card reader%' and exists (select 1 from app.inventory_snapshot s where s.item_code = i.item_code) order by i.item_code limit 10) t on conflict (item_code) do nothing;
insert into app.item_group_item(item_code, group_code) select item_code, 'PAPER' from (select i.item_code from core.v_item i where description ilike '%paper%' and (item_type = 'SUPPLY' or description ilike '%roll%') and exists (select 1 from app.inventory_snapshot s where s.item_code = i.item_code) order by i.item_code limit 10) t on conflict (item_code) do nothing;
insert into app.item_group_item(item_code, group_code) select item_code, 'TONER' from (select i.item_code from core.v_item i where item_type = 'SUPPLY' and description ilike '%toner%' and exists (select 1 from app.inventory_snapshot s where s.item_code = i.item_code) order by i.item_code limit 10) t on conflict (item_code) do nothing;
